"""Offline review page and delivery hashes, using measured reports and real renders."""
from pathlib import Path
import hashlib, html, json
P=Path(__file__).resolve().parent;OUT=P.parent/'review/M01'

def main():
    qa=json.loads((OUT/'validation_summary.json').read_text());renders=json.loads((OUT/'render_manifest.json').read_text())
    assert qa['technical_pass'] and renders['full_review'],'Do not publish a failed candidate as verified'
    cards=''.join(f'<article><a href="{r["file"]}"><img loading="lazy" src="{r["file"]}" alt="{html.escape(r["title"])}"></a><h3>{i:02d} / {html.escape(r["title"]).upper()}</h3></article>' for i,r in enumerate(renders['images'],1))
    dimensions=' × '.join(f'{d/100:.2f}' for d in qa['dimensions_cm'])
    body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rift M01 · Fleet review</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#10101b;color:#e6e1f0;font:16px/1.6 Segoe UI,Arial,sans-serif}}header,main,footer{{max-width:1500px;margin:auto;padding:28px 34px}}header{{border-bottom:1px solid #4e365b}}h1{{font-size:38px;letter-spacing:5px;margin:6px 0}}.tag{{color:#ff7adf;font-size:12px;letter-spacing:3px}}h2{{margin:30px 0 12px}}a{{color:#fca6e9}}.hero{{display:block;width:100%;border-radius:12px}}.metrics{{display:flex;gap:16px;flex-wrap:wrap;margin:24px 0}}.metrics div{{flex:1;min-width:170px;padding:16px;background:#251c35;border:1px solid #574167;border-radius:9px}}.metrics b{{display:block;color:#ffb9ef;font-size:22px}}.metrics span{{font-size:12px;color:#b8a7c9}}.notice{{border-left:3px solid #e955cc;background:#251b31;padding:18px 24px;margin:24px 0}}.notice p{{margin:7px 0}}.grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}}article{{background:#211a2d;border:1px solid #4a375a;border-radius:10px;overflow:hidden}}article img{{display:block;width:100%}}article h3{{font-size:14px;letter-spacing:1px;margin:14px 20px}}.links{{display:flex;flex-wrap:wrap;gap:18px;margin:24px 0}}.small{{font-size:14px;color:#bbaece}}footer{{font-size:13px;color:#b8a7c9;border-top:1px solid #4a375a}}@media(max-width:750px){{.grid{{grid-template-columns:1fr}}header,main,footer{{padding:20px}}h1{{font-size:30px}}}}
</style></head><body><header><div class="tag">TRIAD DRIFT / FLEET FOUNDATION / PHASE 1</div><h1>RIFT / M01</h1><div>Crescent portal specialist · Wren · Magenta squad identity</div></header><main>
<a href="01_hero_front_3q.png"><img class="hero" src="01_hero_front_3q.png" alt="Rift refined foundation front three-quarter"></a>
<div class="metrics"><div><b>{qa['assembly_triangles']:,}</b><span>ASSEMBLED TRIANGLES</span></div><div><b>{dimensions} m</b><span>LENGTH × SPAN × HEIGHT</span></div><div><b>{qa['materials']} / {len(qa['attachment_checks'])}</b><span>MATERIALS / VERIFIED LOCATORS</span></div><div><b>{100*qa['emissive_surface_fraction']:.2f}%</b><span>EMISSIVE TRIANGLE SURFACE AREA</span></div></div>
<div class="notice"><p><strong>Technically verified source foundation — Nick's visual review required.</strong></p><p>A continuous crescent monocoque, compact cockpit, fork-supported nose portal ring, integrated twin Pulse modules and a central Splitter cannon establish Rift's distinct identity. Controlled gloss, violet/plum paint, bare titanium and limited magenta emission retain the fleet's bright sci-fi style.</p><p>Nothing has been imported into Unreal. This preview does not establish final AAA quality, in-game readability or runtime performance. Bastion production remains stopped until Rift approval.</p></div>
<h2>Inspect every angle</h2><p>Click an image for full resolution. Views are independently framed; use the measured dimensions for scale. Weapon and portal close-ups isolate modules for inspection.</p><div class="grid">{cards}</div>
<h2>Construction and silhouette</h2><a href="Rift_M01_clay_sheet.png"><img class="hero" src="Rift_M01_clay_sheet.png" alt="Rift six-angle clay inspection"></a>
<a href="Rift_M01_wire_sheet.png"><img class="hero" src="Rift_M01_wire_sheet.png" alt="Actual mesh-edge wire overlays"></a>
<p class="small">Wire overlays trace actual mesh edges; no wireframe modifier changes the depicted topology. Silhouette source renders below are 128 × 128 pixels, enlarged for inspection.</p><a href="Rift_M01_silhouette_sheet.png"><img class="hero" src="Rift_M01_silhouette_sheet.png" alt="Rift black silhouettes at 128 pixel source resolution"></a>
<p>64 px browser-display check: <img src="silhouette_128_top.png" width="64" height="64" alt="Top silhouette displayed at 64 pixels"> <img src="silhouette_128_side.png" width="64" height="64" alt="Side silhouette displayed at 64 pixels"> <img src="silhouette_128_front_3q.png" width="64" height="64" alt="Three-quarter silhouette displayed at 64 pixels"></p>
<h2>Fleet reference</h2><a href="Lancer_reference_4b7ef12.png"><img class="hero" src="Lancer_reference_4b7ef12.png" alt="Approved Lancer M02 foundation reference"></a><p class="small">Unmodified reference from frozen Lancer 4b7ef12. Independently framed and lit; not a matched-scale or engine comparison. Lancer was preserved unchanged.</p>
<h2>Points for Nick's decision</h2><p>Independent review finds this ready for the same refined-foundation decision as Lancer. Known limitations: the portal becomes a thin bar from the side; its supports are simpler than the flowing hull; broad violet paint reads bright lavender and uniformly fresh; rear and underside structure are sparser than Lancer. These remain visible rather than being treated as final AAA polish.</p>
<h2>Review boundaries and next handoff</h2><p>The independent art assessment and remaining visual limitations are in the report below. Six reusable mesh roles assemble into seven visual parts. Portal rotation, VFX, firing and weapon-specific runtime muzzle binding are not implemented. Current gameplay's generic first-mesh Muzzle_0…N lookup requires engineering review for the separate Splitter origin. All proposed frames are documented, not silently treated as a finalized gameplay API.</p>
<div class="links"><a href="Rift_M01_overview.png">One-image overview</a><a href="report.md">Technical and art review</a><a href="validation_summary.json">Measured QA</a><a href="geometry_qa.json">Geometry details</a><a href="../../production/README.md">Source / integration notes</a><a href="../../production/Rift_M01_v01.blend">Blender source</a><a href="../../production/attachments.json">Attachment manifest</a><a href="../../production/material_parameters.json">Material settings</a></div>
</main><footer>Ships & Weapons Agent · nick/ships-rift · Source foundation only · Native and Bastion work held for review.</footer></body></html>'''
    (OUT/'index.html').write_text(body,encoding='utf-8')
    images=[dict(file=p.name,bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()) for p in sorted(OUT.glob('*.png'))]
    (OUT/'delivery_manifest.json').write_text(json.dumps(dict(images=images,technical_pass=True,manual_approval=False,native_imported=False),indent=2)+'\n')
    print(json.dumps(dict(page=str(OUT/'index.html'),images=len(images),technical_pass=True)))

if __name__=='__main__':main()
